steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      users(filter: {name: {contains: \"Maya Chen\"}}) {
        nodes {
          id
          name
          email
        }
      }
      teams(filter: {name: {contains: \"Web\"}}) {
        nodes {
          id
          name
          key
          projects(filter: {name: {contains: \"Atlas\"}}) {
            nodes {
              id
              name
            }
          }
        }
      }
    }
  }'
